    "parking_bikes" INTEGER NOT NULL DEFAULT 0,
    "parking_cars" INTEGER NOT NULL DEFAULT 0,
    "facing" "Facing",
    "year_built" INTEGER,
    "water_supply" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "electricity_backup" "ElectricityBackup" NOT NULL DEFAULT 'none',
    "internet_available" BOOLEAN NOT NULL DEFAULT false,
    "waste_collection" BOOLEAN NOT NULL DEFAULT false,
