-- ───────── Hand-written additions (not expressible in schema.prisma) ─────────

-- Hot path: public search only ever reads published listings.
CREATE INDEX "listings_published_city_rent_idx"
    ON "listings" ("city_id", "rent_npr", "published_at" DESC)
    WHERE "status" = 'published';

-- Fuzzy matching for neighbourhood / title autocomplete.
CREATE INDEX "listings_title_trgm_idx" ON "listings" USING GIN ("title" gin_trgm_ops);
CREATE INDEX "neighborhoods_name_trgm_idx" ON "neighborhoods" USING GIN ("name" gin_trgm_ops);

-- Integrity guards that belong in the database, not just the app.
ALTER TABLE "listings" ADD CONSTRAINT "listings_rent_positive" CHECK ("rent_npr" > 0);
ALTER TABLE "listings" ADD CONSTRAINT "listings_deposit_nonneg" CHECK ("deposit_npr" IS NULL OR "deposit_npr" >= 0);
ALTER TABLE "listings" ADD CONSTRAINT "listings_rooms_nonneg" CHECK ("bedrooms" >= 0 AND "bathrooms" >= 0);
ALTER TABLE "tour_availability" ADD CONSTRAINT "tour_availability_dow" CHECK ("day_of_week" BETWEEN 0 AND 6);
